// RAII and Stack Unwinding during Exception Propagation

class ResourceGuard {
    const char* id;
public:
    ResourceGuard(const char* n) : id(n) {}
    ~ResourceGuard() { /* Cleanup/Dtor runs during unwind */ }
};

void risky_call() {
    ResourceGuard R2("Inner Scope");
    throw 1; // Initiates stack unwinding
}

void main_call() {
    try {
        ResourceGuard R1("Outer Scope");
        risky_call();
    } catch (int e) {
        // R1 and R2 destroyed (unwound) before execution reaches here
    }
}
